// zen-proxy: bridges opencode (which forces stream:true) to OpenCode Zen free models
// that work reliably only in non-streaming mode on this proot/Android setup.
// Listens locally, receives chat/completions, calls Zen with stream:false,
// then re-emits the result as a single SSE stream so the AI SDK is satisfied.

import http from "node:http";

const ZEN = "https://opencode.ai/zen/v1";
const PORT = 4188;

function send(res, status, body, headers = {}) {
  res.writeHead(status, headers);
  res.end(body);
}

const server = http.createServer((req, res) => {
  let chunks = [];
  req.on("data", (c) => chunks.push(c));
  req.on("end", async () => {
    const raw = Buffer.concat(chunks).toString("utf8");

    // pass-through for GET (e.g. /models)
    if (req.method === "GET") {
      try {
        const r = await fetch(ZEN + req.url.replace(/^\/v1/, ""), {
          headers: { "content-type": "application/json" },
        });
        const t = await r.text();
        return send(res, r.status, t, { "content-type": "application/json" });
      } catch (e) {
        return send(res, 502, JSON.stringify({ error: String(e) }));
      }
    }

    let body;
    try {
      body = JSON.parse(raw || "{}");
    } catch {
      return send(res, 400, JSON.stringify({ error: "bad json" }));
    }

    const wantStream = body.stream === true;
    body.stream = false; // force non-streaming upstream

    const upstreamPath = req.url.replace(/^\/v1/, "");
    let upstream;
    try {
      upstream = await fetch(ZEN + upstreamPath, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify(body),
      });
    } catch (e) {
      return send(res, 502, JSON.stringify({ error: String(e) }));
    }

    const text = await upstream.text();

    if (!wantStream) {
      return send(res, upstream.status, text, {
        "content-type": "application/json",
      });
    }

    // Re-emit the non-streamed completion as one SSE chunk + [DONE]
    let parsed;
    try {
      parsed = JSON.parse(text);
    } catch {
      return send(res, 502, JSON.stringify({ error: "upstream not json", raw: text.slice(0, 300) }));
    }

    const choice = parsed.choices && parsed.choices[0];
    const msg = (choice && choice.message) || {};
    const content = msg.content || "";

    const id = parsed.id || "chatcmpl-proxy";
    const model = parsed.model || body.model;
    const created = parsed.created || Math.floor(Date.now() / 1000);

    res.writeHead(200, {
      "content-type": "text/event-stream",
      "cache-control": "no-cache",
      connection: "keep-alive",
    });

    const chunk = {
      id, object: "chat.completion.chunk", created, model,
      choices: [{ index: 0, delta: { role: "assistant", content }, finish_reason: null }],
    };
    res.write(`data: ${JSON.stringify(chunk)}\n\n`);

    const done = {
      id, object: "chat.completion.chunk", created, model,
      choices: [{ index: 0, delta: {}, finish_reason: choice ? choice.finish_reason || "stop" : "stop" }],
      usage: parsed.usage || undefined,
    };
    res.write(`data: ${JSON.stringify(done)}\n\n`);
    res.write("data: [DONE]\n\n");
    res.end();
  });
});

server.listen(PORT, "127.0.0.1", () => {
  console.log(`zen-proxy listening on http://127.0.0.1:${PORT}/v1 -> ${ZEN} (non-stream bridge)`);
});

