const ACCT = "9f5953f2d2e38c4cbd16bcb2b5ae80a3";
const KEY = "[REDACTED-53chars-ROTATE-REQUIRED]";
const URL = `https://api.cloudflare.com/client/v4/accounts/${ACCT}/ai/v1/chat/completions`;

const tools = [{
  type: "function",
  function: {
    name: "get_weather",
    description: "Get weather for a city",
    parameters: { type: "object", properties: { city: { type: "string" } }, required: ["city"] },
  },
}];

const models = [
  "@cf/meta/llama-3.3-70b-instruct-fp8-fast",
  "@cf/meta/llama-4-scout-17b-16e-instruct",
  "@hf/nousresearch/hermes-2-pro-mistral-7b",
  "@cf/mistralai/mistral-small-3.1-24b-instruct",
  "@cf/qwen/qwen2.5-coder-32b-instruct",
];

for (const model of models) {
  try {
    const r = await fetch(URL, {
      method: "POST",
      headers: { "Authorization": `Bearer ${KEY}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        model,
        messages: [{ role: "user", content: "What is the weather in Cairo? Use the get_weather tool." }],
        tools,
        max_tokens: 200,
      }),
    });
    const j = await r.json();
    if (j.errors) { console.log(`${model} => ERR: ${j.errors[0].message}`); continue; }
    const m = j.choices?.[0]?.message;
    if (m?.tool_calls?.length) {
      console.log(`${model} => TOOLS_OK: ${m.tool_calls[0].function.name}(${m.tool_calls[0].function.arguments})`);
    } else {
      console.log(`${model} => NO_TOOLS, content: ${JSON.stringify((m?.content || "").slice(0, 70))}`);
    }
  } catch (e) {
    console.log(`${model} => EXC: ${String(e).slice(0, 60)}`);
  }
}

