let d='';process.stdin.on('data',c=>c&&(d+=c)).on('end',()=>{
  try{
    let j=JSON.parse(d);
    let cfg=j['\$defs']['Config'];
    let p=cfg.properties||{};
    console.log('Config keys:',Object.keys(p).join(', '));
    for(let k of ['share','autoshare','title','disabled_providers','autoupdate','instructions']){
      if(p[k]) console.log('  '+k+':',JSON.stringify(p[k]).slice(0,150));
    }
    // AgentConfig - look for how to disable an agent
    let ag=j['\$defs']['AgentConfig'];
    if(ag) console.log('AgentConfig keys:',Object.keys(ag.properties||{}).join(', '));
  }catch(e){console.log('ERR',e.message)}
});" 2>&1

