// Find a model that returns NATIVE tool_calls (not raw JSON text)
const tools = [{
  type: "function",
  function: {
    name: "bash",
    description: "Run a shell command",
    parameters: { type: "object", properties: { command: { type: "string" } }, required: ["command"] },
  },
}];

const targets = [
  // OpenCode Zen (free)
  { base: "https://opencode.ai/zen/v1", key: null, models: ["deepseek-v4-flash-free", "north-mini-code-free", "mimo-v2.5-free", "qwen3.6-plus-free", "nemotron-3-ultra-free", "minimax-m3-free"] },
  // Cloudflare
  { base: "https://api.cloudflare.com/client/v4/accounts/9f5953f2d2e38c4cbd16bcb2b5ae80a3/ai/v1", key: "[REDACTED-53chars-ROTATE-REQUIRED]", models: ["@cf/meta/llama-3.3-70b-instruct-fp8-fast", "@cf/meta/llama-4-scout-17b-16e-instruct", "@cf/mistralai/mistral-small-3.1-24b-instruct", "@cf/qwen/qwen2.5-coder-32b-instruct"] },
];

for (const t of targets) {
  for (const model of t.models) {
    try {
      const headers = { "Content-Type": "application/json" };
      if (t.key) headers["Authorization"] = `Bearer ${t.key}`;
      const r = await fetch(t.base + "/chat/completions", {
        method: "POST",
        headers,
        body: JSON.stringify({
          model,
          messages: [{ role: "user", content: "Run the command: echo hi" }],
          tools,
          max_tokens: 300,
        }),
      });
      const j = await r.json();
      if (j.errors) { console.log(`${model} => ERR: ${j.errors[0].message.slice(0,40)}`); continue; }
      const m = j.choices?.[0]?.message;
      const fr = j.choices?.[0]?.finish_reason;
      if (m?.tool_calls?.length) {
        console.log(`${model} => ✅ NATIVE tool_calls (finish=${fr})`);
      } else {
        const c = (m?.content || m?.reasoning_content || "").slice(0, 50);
        console.log(`${model} => ❌ text (finish=${fr}): ${JSON.stringify(c)}`);
      }
    } catch (e) {
      console.log(`${model} => EXC: ${String(e).slice(0,40)}`);
    }
  }
}

